"""Executive summary: finalize a frozen oracle-kill study without implementing or fitting a router.
All unexecuted downstream experiments are explicitly marked NOT_RUN_KILL_GATE.
"""
import csv,io,json,datetime,zipfile
from pathlib import Path
import numpy as np
from .core import ROOT,EXPERTS,PARENT,dump,digest,require_pre,kill_gate
from .oracle_audit import summarize

def finalize(private):
 out=ROOT/'backtesting/last_shot08/results';pre=require_pre(private)
 cards=json.loads((private/'recovered/text/private/cards.json').read_text())['cards'];records=[json.loads((private/'scored'/f'card{i:02d}.json').read_text())for i in range(24)]
 oracle=json.loads((out/'library_oracle_summary.json').read_text());verdict=kill_gate(5,oracle['composite']);assert verdict=='INSUFFICIENT_EXISTING_EXPERT_HEADROOM'
 choices=[min(EXPERTS,key=lambda e:r['models'][e]['ratio'])for r in records]
 # This is an exact archived historical prediction, not a new fitted router.
 zpath=private.parent/'last-shot08-input-archives/text-route-audit02-complete-private-recovery.zip'
 with zipfile.ZipFile(zpath)as z:
  raw=z.read('private/results/loocv_predictions.csv');rows=list(csv.DictReader(io.StringIO(raw.decode())))
 routes={r['card_id']:int(r['route'])for r in rows if r['model']=='T0_RIDGE'};assert len(routes)==24
 historical=summarize(cards,records,['R2'if routes[c['id']]else 'B0'for c in cards]);published=json.loads((ROOT/'backtesting/text_route_audit02/results/router_score_summary.json').read_text())['models']['T0_RIDGE']
 for k in ['composite','arithmetic','marginal','joint','tail']:assert historical[k]==published[k],k
 for group in ['single','multi']:assert historical[group]['composite']==published[group]['composite']
 dump(out/'historical_t0_ridge_reference.json',{'status':'EXACT_ARCHIVED_LOCO_REFERENCE_ONLY','no_refit':True,'prediction_file_sha256':__import__('hashlib').sha256(raw).hexdigest(),'published_summary_sha256':digest(ROOT/'backtesting/text_route_audit02/results/router_score_summary.json'),'score':historical,'not_current_family_holdout':True})
 skipped={'status':'NOT_RUN_KILL_GATE','reason':'Library oracle 0.9277688750836486 > frozen 0.75 threshold; no router implementation or fitting permitted','replicates_executed':0,'not_a_predictive_failure_result':True}
 for name in ['primary_router_summary.json','negative_controls.json','bootstrap_summary.json','oracle_capture.json']:dump(out/name,skipped)
 for name,columns in [('primary_router_predictions.csv',['card_index','family','chosen_expert','status']),('family_holdout_results.csv',['family','composite','status']),('loco_results.csv',['fold','composite','status']),('structural_baselines.csv',['model','composite','status'])]:
  with (out/name).open('w',newline='')as f:csv.writer(f).writerow(['executive_summary',*columns])
 ix=[i for i,c in enumerate(cards)if c['cells']>1];routed=[i for i in ix if choices[i]!='B0']
 jointdamage=sum((records[i]['models'][choices[i]]['joint']/records[i]['baseline']['joint']-1)*.3 for i in routed if records[i]['baseline']['joint']>1e-12)
 safety={'primary':skipped,'oracle_diagnostic_only':{'summary':oracle['multi'],'routed_multi_cards':len(routed),'improved':sum(records[i]['models'][choices[i]]['ratio']<1 for i in routed),'worsened':sum(records[i]['models'][choices[i]]['ratio']>1 for i in routed),'joint_damage_weighted_ratio_sum':float(jointdamage),'worst_routed_multi_ratio':max((records[i]['models'][choices[i]]['ratio']for i in routed),default=None),'F1':oracle['families']['T2-F1']},'expert_multi_components':{e:summarize(cards,records,[e]*24)['multi']for e in EXPERTS},'oracle_safety_does_not_validate_predictive_routing':True}
 dump(out/'multi_safety_summary.json',safety)
 arithmetic=json.loads((out/'arithmetic_sensitivity.json').read_text());arithmetic['historical_T0_RIDGE_2WAY']=historical['arithmetic'];arithmetic['training_global_best']='NOT_RUN_KILL_GATE';dump(out/'arithmetic_sensitivity.json',arithmetic)
 dump(out/'final_decision.json',{'LAST_SHOT08_RESULT':verdict,'oracle_composite':oracle['composite'],'oracle_arithmetic':oracle['arithmetic'],'oracle_threshold':.75,'library_count':5,'router_built':False,'router_fits':0,'no_new_alpha_claim':True,'INDEPENDENT_OOS':False,'submission_performed':False,'official_reference_unchanged':.9541,'PRE_RESULT_LAST_SHOT08_SHA':pre,'parent_result_sha':PARENT})
 dump(out/'next_axis_decision.json',{'NEXT':'V51_SAFE_DELIVERY-09','exactly_one_axis':True,'reason':'Perfect selection among recoverable eligible frozen experts cannot meet the precommitted moonshot headroom threshold','next_study_executed':False})
 statusp=ROOT/'backtesting/last_shot08/STATUS.json';s=json.loads(statusp.read_text());s.update(HEAD_SHA=pre,PRE_RESULT_LAST_SHOT08_SHA=pre,current_stage='FINAL_TESTS',completed_stages=s['completed_stages']+['PRE_REMOTE_VERIFIED','whole_card_historical_scores_exact_120','oracle_kill_gate','historical_T0_reference_exact','final_decision'],pending_stages=['final_tests','result_remote','final_private_recovery'],last_successful_artifact='final_decision.json',last_update_time=datetime.datetime.now(datetime.timezone.utc).isoformat());dump(statusp,s)
 # Preserve the PRE file bytes. The current PRE binding lives in an external receipt.
 dump(out/'pre_result_binding.json',{'PRE_RESULT_LAST_SHOT08_SHA':pre,'remote_verified':True,'tree':'f58169ad758a21cfd68e28262bd3c6db5cc255f5','receipt_sha256':digest(private/'PRE_REMOTE_RECEIPT.json'),'parent':PARENT})
 report=ROOT/'LAST-SHOT-08-FROZEN-EXPERT-ROUTER-report.md'
 def table(rows):return '\n'.join('| '+' | '.join(str(v)for v in row)+' |'for row in rows)
 experts=list(csv.DictReader((out/'expert_aggregate_summary.csv').open()));inventory=list(csv.DictReader((out/'expert_inventory.csv').open()))
 lines=['# LAST-SHOT-08 — Frozen-expert card-conditional meta router','','## Executive summary (read this first)','','Completed the precommitted early-kill study. **INSUFFICIENT_EXISTING_EXPERT_HEADROOM**: five eligible historical expert profiles reproduce exactly on 24 exposed cards / 63 cells (13 single, 11 multi, six cards per family). The future-informed whole-card library oracle is **0.927768875084 geometric / 0.945201950256 arithmetic**, above the frozen 0.75 continuation gate. Therefore no meta-router was implemented, fitted or evaluated. Controls and predictive-router bootstraps were not run, exactly as the kill rule requires. Next axis: **V51_SAFE_DELIVERY-09**; not executed.','','## Library and provenance','','Eligibility was frozen before comparative losses. No current card winners determined membership. B0/B_NUMERIC/TEXT_LOCATION/R1/R2 are prior CONTEXT01 whole-card forecast profiles. B0 and R2 match previously stored TEXT02 draw bytes; R1 uniquely reconstructs using unchanged saved corrections and original adapter; numeric/text-location use original stored baselines and original transform. All 120 card/expert marginal, joint, tail and composite scores reproduce historical CONTEXT01 values **exactly, zero tolerance**. No expert refitted, recalibrated, retuned or newly composed. Every card retains one complete 2,000-draw forecast.','','The inventory contains '+str(len(inventory))+' discovered profiles/categories, of which five are eligible. V11–V13 original recovery files retained reports/aggregate evidence, not original complete coefficients/bank/card draws. Reconstructed variants are distinct artifacts with a 2008-12-31 training cutoff incompatible with earlier proxy origins and no exact complete retained forecasts. Card-label-trained B1–B5/R3 cannot establish fresh family holdout isolation without forbidden refitting. Seven source correction vectors are R1/R2 inputs rather than pre-existing standalone whole-card experts. Controls, B0 aliases and future-informed oracles are excluded. Historical V6–V10/development/tail/joint/continuous diagnostics lack comparable exact full-card profiles. These are technical exclusions, not observed-score exclusions.','','## Same-ledger scores','', '| Model | Geometric | Arithmetic | Marginal | Joint | Tail | Single | Multi |','|---|---:|---:|---:|---:|---:|---:|---:|']
 for r in experts:lines.append('| '+r['expert']+' | '+' | '.join(f"{float(r[k]):.9f}"for k in ['composite','arithmetic','marginal','joint','tail','single','multi'])+' |')
 for name,q in [('LIBRARY_ORACLE (future-informed)',oracle),('T0_RIDGE_2WAY (archived LOCO only)',historical)]:lines.append('| '+name+' | '+' | '.join(f"{q[k]:.9f}"for k in ['composite','arithmetic','marginal','joint','tail'])+f" | {q['single']['composite']:.9f} | {q['multi']['composite']:.9f} |")
 lines+=['| T0_MULTIEXPERT_RIDGE / training-global-best / S0 / ST0 | NOT RUN | NOT RUN | — | — | — | — | — |','','The archived T0 Ridge row is a previously exposed secondary LOCO diagnostic. It was reconstructed from archived route choices and the reproduced frozen losses without refitting. It is not LAST-SHOT08 family-holdout evidence. Training-global-best, TRAINING_FAMILY_BEST, primary family holdout and secondary LOCO were not executed after the gate. The held-family training mapping would additionally be unestimable for an unseen family without an independently fixed mapping.','','## Oracle gate and family detail','','Headroom = '+f"{100*oracle['headroom']:.6f}%"+'. This is descriptive achievable selection headroom **within this recoverable library**, not evidence that text predicts those choices. It does not bound all hypothetical future experts or perfect-location headroom. No comparison to an official score is licensed. Arithmetic is below one; geometric-only headroom risk is false.','','| Family | Oracle geometric | Arithmetic | Marginal | Joint |','|---|---:|---:|---:|---:|']
 for f,v in oracle['families'].items():lines.append(f"| {f} | {v['composite']:.9f} | {v['arithmetic']:.9f} | {v['marginal']:.9f} | "+('N/A single-cell family'if v['joint']is None else f"{v['joint']:.9f}")+' |')
 con=json.loads((out/'concentration_summary.json').read_text())
 lines+=['','Oracle winner counts (deterministic B0-first tie handling): '+', '.join(f'{e}={n}'for e,n in oracle['winner_counts'].items())+'. Only six cards require a non-B0 winning expert; B_NUMERIC never wins. Anonymous best-card ratio '+f"{oracle['best_card_ratio']:.9f}"+', worst-card ratio '+f"{oracle['worst_card_ratio']:.9f}"+'. Individual answers and winner identities remain private.','','## Multi safety and concentration','','Future-informed oracle multi composite '+f"{oracle['multi']['composite']:.9f}"+', marginal '+f"{oracle['multi']['marginal']:.9f}"+', joint '+f"{oracle['multi']['joint']:.9f}"+', tail '+f"{oracle['multi']['tail']:.9f}"+'. It selects non-B0 on '+str(len(routed))+' multi cards. All these selections improve total composite; this hindsight property cannot validate predictive multi safety. R1 always has multi composite 1.117294774 and R2 always 1.024591690, reinforcing the need for a separate predictive safety gate if routing had proceeded. F1 oracle composite '+f"{oracle['families']['T2-F1']['composite']:.9f}"+'.','','Gross arithmetic ratio-gain concentration: largest card '+f"{100*con['largest_card_fraction']:.4f}%"+', largest family '+f"{100*con['largest_family_fraction']:.4f}%"+', single cards '+f"{100*con['single_fraction']:.4f}%"+', multi cards '+f"{100*con['multi_fraction']:.4f}%"+'. CARD_CONCENTRATED=true (>40%); FAMILY_CONCENTRATED=false (<=60%). R1 supplies '+f"{100*con['expert_fraction']['R1']:.4f}%"+' of gross oracle gain. No card or family was removed.','','## Frozen feature/model scope and non-executed stages','','T0 has exactly 36 inherited lexical/count columns; S0=13 and ST0=49. Source feature NPZ SHA256 564a38e4b7d71dca0ae7c22270486edca47195e7b89c27afce9989e646c7df67; all three arrays reproduce bitwise. No new annotations/embeddings/card-ID/outcome features. The conditional Ridge alpha=1, train-only scaling, four family holdouts, LOCO secondary, seed31808, six controls and 5,000 card/family bootstraps remain documented in PRE but were not implemented/run because the oracle gate failed. MC p-values, predictive oracle capture and bootstrap intervals are **N/A**, not zero and not inferred. All downstream output placeholders explicitly say NOT_RUN_KILL_GATE or are empty header-only tables.','','## Execution, recovery and limitations','','The session was interrupted during PRE publication: transient worktree/private bytes disappeared before comparative outcomes were accessed. The already-created remote tree f58169ad758a21cfd68e28262bd3c6db5cc255f5 preserved the 15 PRE files. They were recovered byte-for-byte, the same source archives reacquired because local copies were missing, and frozen forecast/feature identities reverified. No scientific specification changed. PRE remote receipt was bound before truth or comparative scores were deserialized. Prior operational metadata key and test-environment dependency repairs did not change scientific code. The initial local staged tree differed from the remote-created tree; the recovered remote file bytes give an exact matching local tree and all parent file blobs remain unchanged.','','All 24 cards are already exposed; INDEPENDENT_OOS=false. The unchanged research proxy scorer uses baseline-relative components, not sealed official reference scales. This study creates no new location alpha, supports no submission and does not establish text-routing prediction. Historical V5.1 Development 0.9541 is preserved as a reference, not re-estimated or multiplied by proxy ratios. Provenance recovery was not reopened; official uploaded-image/source linkage remains unresolved from parent07. Main, all 2,497 inherited files and 132 protected V5.1/package files remain unchanged. No Docker build/forecast rerun/submission/next research executed.','','## Git identities and validation','','Scientific parent: `'+PARENT+'`. PRE_RESULT_LAST_SHOT08_SHA: `'+pre+'`. RESULT is recorded by final remote verification and private completion receipt (a commit cannot contain its own SHA). Final test counts/log hashes are in execution_audit.json; report and aggregates are in RESULT. A new final private ZIP includes complete frozen forecasts, private score ledger, source manifests, code/tests/PRE/Git metadata and final evidence; CRC, each member SHA256 and ZIP SHA256 are verified and saved.']
 report.write_text('\n'.join(lines)+'\n')
 print('Final decision/report written; no router built',flush=True)
